const pd=s=>{const [y,m,d]=String(s||'').split('-').map(Number);return new Date(y||2026,(m||1)-1,d||1)};
const today=()=>{const t=new Date();return new Date(t.getFullYear(),t.getMonth(),t.getDate())};
const fdate=(s,soloMes)=>{const d=pd(s);return soloMes?`${MESES[d.getMonth()]} de ${d.getFullYear()}`:`${d.getDate()} de ${MESES[d.getMonth()]} de ${d.getFullYear()}`};
const com=id=>(S.comisiones||[]).find(c=>c.id===id)||{id,nombre:id,color:'#10265E'};
const para=t=>String(t||'').split(/\n\s*\n/).map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('');
const initials=n=>String(n||'').trim().split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toUpperCase()||'?';
function toast(msg){let t=$('.toast');if(!t){t=document.createElement('div');t.className='toast';t.setAttribute('role','status');document.body.appendChild(t)}t.textContent=msg;t.classList.add('on');clearTimeout(t._h);t._h=setTimeout(()=>t.classList.remove('on'),3800)}

const logo=id=>{const f=((S.marca||{}).archivos||[]).find(x=>x.id===id);return f?f.src:''};
const comLogo=(c,cls)=>c.logo&&pic(c.logo)?`<img class="comlogo ${cls||''}" src="${esc(pic(c.logo))}" alt="Escudo de la comisión ${esc(c.nombre)}">`:comLogo(c);
const mails=v=>String(v||'').split(/[,;]\s*/).filter(Boolean);
const pic=v=>{v=String(v||'');if(v.startsWith('logo:'))return logo(v.slice(5));if(v.startsWith('galeria:')){const g=(S.galeria||[]).find(x=>x.id===v.slice(8));return g?g.src:''}return v};
const picAlt=v=>{v=String(v||'');if(v.startsWith('galeria:')){const g=(S.galeria||[]).find(x=>x.id===v.slice(8));return g?(g.alt||g.caption||''):''}return ''};
const IC={send:'<path d="M4 12 20 4l-6 16-3-7z"/><path d="m11 13 9-9"/>',users:'<circle cx="9" cy="8" r="3.2"/><path d="M3 20c0-3.3 2.7-6 6-6s6 2.7 6 6"/><path d="M16 5.2a3 3 0 0 1 0 5.6M18 14.3c1.8.8 3 2.6 3 4.7"/>',cal:'<rect x="3.5" y="5" width="17" height="15.5" rx="2"/><path d="M3.5 10h17M8 3v4M16 3v4"/>',doc:'<path d="M6 3h8l4 4v14H6z"/><path d="M14 3v4h4M9 12h6M9 16h6"/>',law:'<path d="M12 3v18M6 21h12M4 7h16M7 7l-3 7h6zM17 7l-3 7h6z"/>',hist:'<path d="M3 12a9 9 0 1 0 3-6.7"/><path d="M3 4v4h4M12 7v5l3 2"/>',flag:'<path d="M5 21V4M5 4h11l-2 4 2 4H5"/>',mega:'<path d="M3 10v4h3l7 4V6L6 10z"/><path d="M17 9a4 4 0 0 1 0 6"/>',phone:'<path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2z"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',left:'<path d="M15 5l-7 7 7 7"/>',right:'<path d="M9 5l7 7-7 7"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',route:'<circle cx="6" cy="18" r="2.5"/><circle cx="18" cy="6" r="2.5"/><path d="M8.5 18H15a3 3 0 0 0 0-6H9a3 3 0 0 1 0-6h6.5"/>',chart:'<path d="M4 20V4M4 20h16"/><path d="M8 16v-4M12 16V8M16 16v-6"/>',photo:'<rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="9" cy="10" r="2"/><path d="m21 16-5-5-9 8"/>',q:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9.5a2.5 2.5 0 1 1 3.5 2.3c-.6.3-1 .9-1 1.6V14M12 17v.5"/>',pin:'<path d="M12 21s-7-6.2-7-11.5a7 7 0 0 1 14 0C19 14.8 12 21 12 21z"/><circle cx="12" cy="9.5" r="2.5"/>',x:'<path d="M6 6l12 12M18 6 6 18"/>',ext:'<path d="M14 4h6v6M20 4l-9 9M18 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h5"/>',moon:'<path d="M20 14.5A8 8 0 0 1 9.5 4 8 8 0 1 0 20 14.5z"/>',net:'<circle cx="12" cy="5" r="2.5"/><circle cx="5" cy="18" r="2.5"/><circle cx="19" cy="18" r="2.5"/><path d="M10.8 7.2 6.3 15.8M13.2 7.2l4.5 8.6M7.5 18h9"/>',mic:'<rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5.5 11a6.5 6.5 0 0 0 13 0M12 17.5V21M8.5 21h7"/>',down:'<path d="M12 4v11M7 10l5 5 5-5M5 20h14"/>',spark:'<path d="M12 3l1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8z"/><path d="M19 15l.8 2.2L22 18l-2.2.8L19 21l-.8-2.2L16 18l2.2-.8z"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="2"/>',shield:'<path d="M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z"/><path d="m9 12 2 2 4-4"/>'};
const MEGA=`<svg class="mega" viewBox="0 0 320 260" role="img" aria-label="Megáfono de la Mesa"><defs><linearGradient id="mgB" x1="0" x2="1"><stop offset="0" stop-color="#2456C9"/><stop offset="1" stop-color="#10265E"/></linearGradient></defs><g fill="none" stroke="#E9B949" stroke-width="7" stroke-linecap="round" opacity=".95"><path d="M236 92q22 38 0 76"/><path d="M258 72q36 58 0 116" opacity=".7"/><path d="M280 52q50 78 0 156" opacity=".45"/></g><g transform="rotate(-8 140 130)"><path d="M58 104h34l92-48v148l-92-48H58a14 14 0 0 1-14-14v-24a14 14 0 0 1 14-14z" fill="url(#mgB)"/><path d="M184 56c16 10 26 42 26 74s-10 64-26 74c-8-12-14-42-14-74s6-62 14-74z" fill="#E9B949"/><path d="M192 98c5 9 8 20 8 32s-3 23-8 32" fill="none" stroke="#8A5F00" stroke-width="5" stroke-linecap="round"/><rect x="70" y="156" width="26" height="54" rx="10" fill="#0B1430"/><rect x="40" y="110" width="12" height="40" rx="6" fill="#E9B949"/><g fill="#E9B949"><circle cx="122" cy="130" r="9"/></g><g stroke="#E9B949" stroke-width="3" stroke-linecap="round">${Array.from({length:10},(_,k)=>{const a=k*36*Math.PI/180;return `<line x1="${(122+Math.cos(a)*14).toFixed(1)}" y1="${(130+Math.sin(a)*14).toFixed(1)}" x2="${(122+Math.cos(a)*22).toFixed(1)}" y2="${(130+Math.sin(a)*22).toFixed(1)}"/>`}).join('')}</g></g></svg>`;
const ico=(n,c)=>`<svg class="ic ${c||''}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${IC[n]||''}</svg>`;
function stitle(eb,t,sub,link,center){return `<div class="st${center?' c':''}"><div>${eb?`<span class="eyebrow">${esc(eb)}</span>`:''}<h2>${esc(t)}</h2><div class="st-rule"></div>${sub?`<p class="muted">${esc(sub)}</p>`:''}</div>${link?`<a class="st-link" href="${esc(link[0])}">${esc(link[1])} ${ico('arrow')}</a>`:''}</div>`}
function ncard(n){return `<a class="ncard" data-cat="${esc(n.categoria)}" href="#/noticia/${esc(n.id)}"><div class="ncard-ph">${media(n.imagen,n.ilustracion,'',picAlt(n.imagen))}<span class="ntag">${esc(n.categoria)}</span></div><div class="body"><div class="meta">${ico('cal')} ${esc(fdate(n.fecha))}</div><h3>${esc(n.titulo)}</h3><p>${esc(n.resumen)}</p><span class="more">Leer más ${ico('arrow')}</span></div></a>`}
function media(src,name,cls,alt){src=pic(src);return `<div class="img ${cls||''}">${src?`<img src="${esc(src)}" alt="${esc(alt||'')}" decoding="async">`:illo(name||'sol')}</div>`}
function phead(title,lead,ill,crumb){const f=pic((S.config.cabeceras||{})[parseHash().r]);return `<section class="phead${f?' has-ph':''}">${f?`<img class="phead-bg" src="${esc(f)}" alt="">`:''}<div class="wrap"><nav class="crumbs" aria-label="Ruta de navegación"><a href="#/inicio">Inicio</a><span aria-hidden="true">›</span><span>${esc(crumb||title)}</span></nav><h1>${esc(title)}</h1>${lead?`<p class="lead">${esc(lead)}</p>`:''}</div></section>`}

