const IMGK=['foto','foto2','imagen','src','fotoComisiones','fotoMomentos','fotoLlamado'],LONGK=['p','cuerpo','texto','bio','desc','descripcion','resumen','intro','mision','vision','proposito','boilerplate','heroTexto','d','a'];
